package co.sena.academic.adapter.out.persistence;
import co.sena.academic.application.port.out.LearningOutcomeRepositoryPort; import co.sena.academic.domain.exception.*; import co.sena.academic.domain.model.LearningOutcome; import org.springframework.dao.*; import org.springframework.data.domain.*; import org.springframework.data.jpa.domain.Specification; import org.springframework.stereotype.Component; import java.util.*;
@Component public class LearningOutcomePersistenceAdapter implements LearningOutcomeRepositoryPort {private final LearningOutcomeJpaRepository repo; public LearningOutcomePersistenceAdapter(LearningOutcomeJpaRepository repo){this.repo=repo;} public LearningOutcome save(LearningOutcome v){try{return LearningOutcomeJpaMapper.toDomain(repo.saveAndFlush(LearningOutcomeJpaMapper.toEntity(v)));}catch(OptimisticLockingFailureException e){throw new RowVersionMismatchException(v.getId());}catch(DataIntegrityViolationException e){throw new LearningOutcomeCodeAlreadyExistsException(v.getCompetencyId(),v.getCode());}} public Optional<LearningOutcome> findById(UUID id){return repo.findById(id).map(LearningOutcomeJpaMapper::toDomain);} public boolean existsByCompetencyIdAndCode(UUID c,String code){return repo.existsByCompetencyIdAndCode(c,code);} public boolean existsByCompetencyIdAndCodeAndIdNot(UUID c,String code,UUID id){return repo.existsByCompetencyIdAndCodeAndIdNot(c,code,id);} public List<LearningOutcome> findAll(UUID c,Optional<Boolean>a,int p,int s,Optional<String>sort){return repo.findAll(spec(c,a),PageRequest.of(p,s,order(sort))).map(LearningOutcomeJpaMapper::toDomain).getContent();} public long count(UUID c,Optional<Boolean>a){return repo.count(spec(c,a));} private static Specification<LearningOutcomeJpaEntity> spec(UUID c,Optional<Boolean>a){Specification<LearningOutcomeJpaEntity>x=(r,q,b)->b.equal(r.get("competencyId"),c);return a.map(v->x.and((r,q,b)->b.equal(r.get("active"),v))).orElse(x);} private static Sort order(Optional<String>s){String[]p=s.orElse("created_at:desc").split(":",2);String f=switch(p[0]){case "code"->"code";case "description"->"description";case "is_active"->"active";case "updated_at"->"updatedAt";default->"createdAt";};return Sort.by(p.length>1&&"asc".equalsIgnoreCase(p[1])?Sort.Direction.ASC:Sort.Direction.DESC,f);}}
